--
-- Table structure for table `claims`
--

DROP TABLE IF EXISTS `claims`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `claims` (
  `claim_id` varchar(30) NOT NULL,
  `claimant_id` varchar(30) NOT NULL,
  `policy_id` varchar(30) DEFAULT NULL,
  `incident_id` varchar(30) DEFAULT NULL,
  `claim_date` date DEFAULT NULL,
  `claimed_amount` decimal(12,2) DEFAULT NULL,
  `approved_amount` decimal(12,2) DEFAULT NULL,
  `claim_status` varchar(30) DEFAULT NULL,
  `description` text,
  PRIMARY KEY (`claim_id`),
  KEY `claimant_id` (`claimant_id`),
  KEY `policy_id` (`policy_id`),
  KEY `incident_id` (`incident_id`),
  CONSTRAINT `claims_ibfk_1` FOREIGN KEY (`claimant_id`) REFERENCES `claimants` (`claimant_id`),
  CONSTRAINT `claims_ibfk_2` FOREIGN KEY (`policy_id`) REFERENCES `policies` (`policy_id`),
  CONSTRAINT `claims_ibfk_3` FOREIGN KEY (`incident_id`) REFERENCES `incidents` (`incident_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

